"""Builds a synthetic test set. Every value is fake, generated by Faker; never add real PHI here."""

import json
import random
import re
import string
from pathlib import Path

from faker import Faker

SEED = 7
SAMPLES_PER_TEMPLATE = 8
OUTPUT = Path(__file__).parent / "data" / "synthetic.jsonl"
NON_BLOCKING_TYPES = {"DATE_TIME"}

fake = Faker("en_US")
DATE_FORMATS = ["%m/%d/%Y", "%Y-%m-%d", "%m-%d-%Y", "%B %d, %Y"]
CDT_CODES = [
    "D0120",
    "D0150",
    "D0210",
    "D1110",
    "D2391",
    "D2740",
    "D2950",
    "D3330",
    "D4341",
    "D7140",
]
PAYERS = ["Delta Dental", "MetLife", "Cigna Dental", "Aetna", "Guardian", "United Concordia"]
MBI_LETTERS = "ACDEFGHJKMNPQRTUVWXY"


def digits(n: int) -> str:
    return "".join(random.choices(string.digits, k=n))


def letters(n: int) -> str:
    return "".join(random.choices(string.ascii_uppercase, k=n))


def date(dt) -> str:
    return dt.strftime(random.choice(DATE_FORMATS))


def member_id() -> str:
    return random.choice([letters(3) + digits(9), "W" + digits(9), digits(11), digits(9) + "01"])


def mbi() -> str:
    alnum = MBI_LETTERS + string.digits
    return (
        random.choice("123456789")
        + random.choice(MBI_LETTERS)
        + random.choice(alnum)
        + digits(1)
        + random.choice(MBI_LETTERS)
        + random.choice(alnum)
        + digits(1)
        + "".join(random.choices(MBI_LETTERS, k=2))
        + digits(2)
    )


# slot name -> (gold PHI type, or None when the value is not PHI, value generator)
SLOTS = {
    "PERSON": ("PERSON", fake.name),
    "PERSON_LOWER": ("PERSON", lambda: fake.name().lower()),
    "FIRST": ("PERSON", fake.first_name),
    "LAST": ("PERSON", fake.last_name),
    "DOB": ("DATE_TIME", lambda: date(fake.date_of_birth(minimum_age=2, maximum_age=90))),
    "DOB_X12": (
        "DATE_TIME",
        lambda: fake.date_of_birth(minimum_age=2, maximum_age=90).strftime("%Y%m%d"),
    ),
    "DOS": ("DATE_TIME", lambda: date(fake.date_between("-1y", "today"))),
    "SSN": ("US_SSN", fake.ssn),
    "PHONE": ("PHONE_NUMBER", fake.phone_number),
    "EMAIL": ("EMAIL_ADDRESS", fake.email),
    "STREET": ("STREET_ADDRESS", fake.street_address),
    "CITY": ("LOCATION", fake.city),
    "ZIP": ("ZIP_CODE", fake.zipcode),
    "MEMBER_ID": ("MEMBER_ID", member_id),
    "GROUP": (
        "GROUP_NUMBER",
        lambda: random.choice([digits(6), digits(8), letters(2) + digits(5)]),
    ),
    "CLAIM": ("CLAIM_NUMBER", lambda: digits(random.choice([10, 12, 15]))),
    "MBI": ("MEDICARE_ID", mbi),
    "MRN": ("ACCOUNT_NUMBER", lambda: digits(random.choice([6, 7, 8]))),
    "STATE": (None, fake.state_abbr),
    "PROVIDER": (None, lambda: f"Dr. {fake.last_name()}"),
    "NPI": (None, lambda: digits(10)),
    "CDT": (None, lambda: random.choice(CDT_CODES)),
    "TOOTH": (None, lambda: str(random.randint(1, 32))),
    "PAYER": (None, lambda: random.choice(PAYERS)),
    "AMOUNT": (None, lambda: f"{random.uniform(40, 2500):.2f}"),
    "COUNT": (None, lambda: str(random.randint(2, 5000))),
    "VERSION": (
        None,
        lambda: f"{random.randint(1, 5)}.{random.randint(0, 20)}.{random.randint(0, 9)}",
    ),
    "RELEASE_DATE": (None, lambda: date(fake.date_between("-1y", "+1y"))),
    "TIMESTAMP": (None, lambda: fake.date_time_this_year().isoformat(sep=" ", timespec="seconds")),
}

PHI_TEMPLATES = [
    (
        "Can you help me write an appeal letter for {PERSON} (DOB {DOB}), member ID {MEMBER_ID}? "
        "Claim {CLAIM} for {CDT} on tooth #{TOOTH} was denied by {PAYER}."
    ),
    "Patient {PERSON}, SSN {SSN}, called about a balance of ${AMOUNT}.",
    '{"patientName": "{PERSON}", "dob": "{DOB}", "memberId": "{MEMBER_ID}", "groupNumber": "{GROUP}"}',
    "patient_name,dob,member_id,claim_no\n{PERSON},{DOB},{MEMBER_ID},{CLAIM}\n{PERSON},{DOB},{MEMBER_ID},{CLAIM}",
    "{TIMESTAMP} ERROR EligibilityService - verification failed for subscriber {MEMBER_ID} ({PERSON}), payer={PAYER}",
    "| {MRN} | {PERSON} | {DOB} | {PHONE} |\n| {MRN} | {PERSON} | {DOB} | {PHONE} |",
    (
        "Why does this 837D fail validation? NM1*IL*1*{LAST}*{FIRST}****MI*{MEMBER_ID}~N3*{STREET}~"
        "N4*{CITY}*{STATE}*{ZIP}~DMG*D8*{DOB_X12}*F~"
    ),
    "Send the statement to {PERSON} at {STREET}, {CITY}, {STATE} {ZIP}.",
    "Email from {EMAIL}: hi, this is {FIRST}, my claim {CLAIM} still shows pending. Call me at {PHONE}.",
    (
        "Summarize this note: Pt {PERSON} presented with pain on #{TOOTH}. {PROVIDER} recommended {CDT}. "
        "Pt DOB {DOB}. Ins: {PAYER}, Sub ID {MEMBER_ID}, Grp {GROUP}."
    ),
    "MBI {MBI} for {PERSON} is not matching in the eligibility response, what could be wrong?",
    "MRN: {MRN}\nName: {PERSON}\nPhone: {PHONE}\nDOS: {DOS}\nProcedure: {CDT}",
    "debug this: patient = Patient(name='{PERSON}', ssn='{SSN}', dob='{DOB}')",
    "Insurance verification for {FIRST} {LAST}: subscriber is spouse {PERSON}, policy # {MEMBER_ID}, group {GROUP}.",
    "Write a polite reply to {PERSON} ({EMAIL}) explaining that claim #{CLAIM} was paid ${AMOUNT} on {DOS}.",
    "can u check why {PERSON_LOWER} claim got denied, dos {DOS}",
    "{PERSON} {PHONE}",
    "Called {PAYER} re: {FIRST} {LAST}, call ref 48213. Rep said claim {CLAIM} needs x-rays for {CDT}.",
]

CLEAN_TEMPLATES = [
    "What does CARC code CO-197 mean on a dental EOB and how do we appeal it?",
    "Write a Python function that validates an NPI number using the Luhn algorithm.",
    "def get_patient(patient_id: int) -> Patient:\n    return db.query(Patient).filter(Patient.id == patient_id).first()",
    "{TIMESTAMP} INFO ClaimWorker - processed {COUNT} claims in {COUNT}ms",
    "Our release on {RELEASE_DATE} includes the new eligibility module (v{VERSION}).",
    "Explain the difference between {CDT} and {CDT} for billing purposes.",
    "{PROVIDER} wants to know the frequency limitation for {CDT} with {PAYER}.",
    "How should I structure a SQL query to count denied claims per payer per month?",
    "SELECT member_id, group_number, claim_status FROM claims WHERE payer_id = 'BCBS' AND created_at > '2025-01-01';",
    "The NPI for the billing provider is {NPI} and the taxonomy code is 1223G0001X.",
    "Fix this regex: ^\\d{3}-\\d{2}-\\d{4}$ should match the SSN format",
    "Generate a test fixture with 5 fake patients using the Faker library.",
    "Draft a team announcement: the {PAYER} portal will be down for maintenance on {RELEASE_DATE}.",
    "Total AR over 90 days is ${AMOUNT} across {COUNT} accounts.",
    "Patient count dropped to {COUNT} this week; can you build a chart of weekly new patients?",
    "Our PR #{COUNT} changes the claim retry logic, can you review it?",
]

SLOT_PATTERN = re.compile(r"\{([A-Z_0-9]+)\}")


def fill(template: str) -> dict:
    text, entities, cursor = "", [], 0
    for match in SLOT_PATTERN.finditer(template):
        if match.group(1) not in SLOTS:
            continue
        gold_type, generate = SLOTS[match.group(1)]
        value = generate()
        text += template[cursor : match.start()]
        if gold_type:
            entities.append({"type": gold_type, "start": len(text), "end": len(text) + len(value)})
        text += value
        cursor = match.end()
    text += template[cursor:]
    has_phi = any(e["type"] not in NON_BLOCKING_TYPES for e in entities)
    return {"text": text, "entities": entities, "has_phi": has_phi}


def main():
    random.seed(SEED)
    Faker.seed(SEED)
    samples = [
        fill(t) for t in PHI_TEMPLATES + CLEAN_TEMPLATES for _ in range(SAMPLES_PER_TEMPLATE)
    ]
    OUTPUT.parent.mkdir(exist_ok=True)
    OUTPUT.write_text("".join(json.dumps(s) + "\n" for s in samples))
    print(f"Wrote {len(samples)} samples to {OUTPUT}")


if __name__ == "__main__":
    main()
